bad_example:
let list_arr: ListArray = ...;
for i in 0..list_arr.len() {
    let inner = list_arr.value(i);
    let float_arr = inner.as_any().downcast_ref::<Float32Array>().unwrap();
    // BUG: float_arr.values() returns the FULL underlying buffer,
    // not a slice for just element i. Reading float_arr.value(0)
    // gives the first element of the ENTIRE array, not element i.
    for j in 0..float_arr.len() {
        let val = float_arr.value(j); // WRONG: reads from wrong position
    }
}

good_example:
use arrow::array::{ListArray, Float32Array};

let list_arr: ListArray = ...;
for i in 0..list_arr.len() {
    if list_arr.is_null(i) { continue; }
    let offsets = list_arr.value_offsets();
    let start = offsets[i] as usize;
    let end = offsets[i + 1] as usize;
    let inner = list_arr.value(i);
    let float_arr = inner.as_any().downcast_ref::<Float32Array>().unwrap();
    // Correct: use the offset to index into the flat buffer
    for j in start..end {
        let val = float_arr.value(j); // RIGHT: reads from absolute position
    }
}
